'use strict';
const fs=require('node:fs'),os=require('node:os'),path=require('node:path');const {gunzipSync,gzipSync}=require('node:zlib');
const {createDb}=require('../src/db');const {createFictionStore}=require('../src/modules/fiction/store');const {createFictionMedia}=require('../src/modules/fiction/media');const {createFictionLibrary}=require('../src/modules/fiction/library');const {createReferenceBundles}=require('../src/modules/fiction/reference-bundles');
describe('B5 private reference portability',()=>{
 let db,root,library,bundles,world;
 beforeEach(()=>{root=fs.mkdtempSync(path.join(os.tmpdir(),'inkrefs-'));db=createDb(':memory:');const store=createFictionStore(db);const providers={exposure:()=>({}),resolve:()=>{}};const media=createFictionMedia({db,store,rootDir:root});library=createFictionLibrary({db,store,media,providers});bundles=createReferenceBundles({db,library,media});world=library.create('world',{name:'Quiet country',description:'Public mountains.',data:{setting:'Mountain winter',lore:'PRIVATE mountain secret'}});});
 afterEach(()=>{db.close();fs.rmSync(root,{recursive:true,force:true});});
 test('private data is explicit, duplicate names create independent copies, replay creates no extra entries',async()=>{const bytes=bundles.exportBundle([world.id]);const preview=await bundles.preview(bytes);expect(preview.entries[0]).toMatchObject({name:world.name,same_name:true});expect(gunzipSync(bytes).toString()).toContain('PRIVATE mountain secret');const imported=await bundles.importBundle(bytes,'import');expect(imported.ids).toHaveLength(1);expect(imported.ids[0]).not.toBe(world.id);expect((await bundles.importBundle(bytes,'import')).ids).toEqual(imported.ids);expect(library.list('world').entries).toHaveLength(2);library.remove(imported.ids[0],0);await expect(bundles.importBundle(bytes,'import')).rejects.toMatchObject({code:'CREATION_RESULT_DELETED'});});
 test('unknown fields and reused keys with changed content fail before catalogue writes',async()=>{const bytes=bundles.exportBundle([world.id]);await bundles.importBundle(bytes,'import');const value=JSON.parse(gunzipSync(bytes));value.entries[0].entry.name='Another';await expect(bundles.importBundle(gzipSync(JSON.stringify(value)),'import')).rejects.toMatchObject({code:'IDEMPOTENCY_CONFLICT'});value.credential='forbidden';await expect(bundles.importBundle(gzipSync(JSON.stringify(value)),'bad')).rejects.toThrow();expect(library.list('world').entries).toHaveLength(2);});
 test('transaction failure leaves no partial copies or receipt',async()=>{const bytes=bundles.exportBundle([world.id]);db.exec("CREATE TRIGGER refuse_bundle BEFORE INSERT ON fiction_local_receipts BEGIN SELECT RAISE(ABORT,'Injected receipt failure');END;");await expect(bundles.importBundle(bytes,'broken')).rejects.toThrow('Injected receipt failure');expect(library.list('world').entries).toHaveLength(1);expect(db.prepare('SELECT count(*) AS n FROM fiction_local_receipts').get().n).toBe(0);});
});

describe('B5 media portability HTTP security',()=>{
 const request=require('supertest');const {createTestApp}=require('./helpers');
 test('new collection, bundle and painting routes require authentication before body parsing',async()=>{const root=fs.mkdtempSync(path.join(os.tmpdir(),'b5-auth-'));const fixture=createTestApp({authRequired:true,imageDir:root});try{for(const route of ['/api/fiction/private/assets','/api/fiction/private/assets/private/thumbnail','/api/fiction/private/assets/jobs/key'])expect((await request(fixture.app).get(route)).status).toBe(401);for(const route of ['/api/fiction/reference-bundles/import','/api/fiction/private/assets/upload','/api/fiction/private/assets/paint'])expect((await request(fixture.app).post(route).set('Content-Type','application/octet-stream').send(Buffer.from('bad'))).status).toBe(401);}finally{fixture.close();fs.rmSync(root,{recursive:true,force:true});}});
});
